test("shared due per holder scenario 1", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-20");
  expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "clerk-limit", "1.50");
  await ui.setSetting(pg_uma, "floor", "0.50");
  await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
  await ui.setSetting(pg_uma, "perm-void", "clerk");
  expect(await ui.setRole(pg_uma, "wes", "viewer")).toBe(true);
  await ui.setSetting(pg_uma, "note-threshold", "2.50");
  await ui.setSetting(pg_uma, "entry-date", "2026-03-05");
  expect(await ui.addHoliday(pg_uma, "2026-03-16")).toBe(true);
  await ui.setSetting(pg_uma, "grace-B", "2");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "7.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "7.50"})).toBe(true);
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B", "contact": "ADA@X"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C"}));
  expect(await ui.addPool(pg_uma, "P1")).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Cam", "share": "50.00"})).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ada", "share": "50.00"})).toBe(true);
  expect(await ui.addCrew(pg_uma, "C1", "Cam")).toBe(true);
  expect(await ui.addCrewMember(pg_uma, "C1", "Ada")).toBe(true);
  expect(await ui.editPerson(pg_uma, p_cam, {"terms": "3", "termsFrom": "2026-03-12"})).toBe(true);
  const pl_ada_1 = ui.must(await ui.addPlan(pg_uma, p_ada, {"amount": "0.04", "start": "2026-03-09", "end": "2026-04-30", "every": "10"}));
  expect(await ui.retire(pg_uma, p_ada, "2026-03-20")).toBe(true);
  expect(await ui.statement(pg_uma, p_cam)).toBe(true);
  await ui.setToday(pg_uma, "2026-04-13");
  const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "7.77", "note": "n", "ref": "R-2", "tags": "a, B"}));
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "33.33", "from": "2026-04-28"})).toBe(true);
  await ui.showRetired(pg_uma, true);
  expect(await ui.statementAsOf(pg_uma, p_ada, "2026-02-25")).toBe(false);
  expect(await ui.pasteClaims(pg_uma, "Zed,25.00,,a, b\nAda,4.00,,")).toBeNull();
  await ui.refresh(pg_uma);
  await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("n/a");
  await expect(pg_uma.getByTestId("rollup-claimed-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-overdue-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("rollup-overdue-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-settled-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-open-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("bulk-settle-batch")).toHaveText("");
  await expect(pg_uma.getByTestId("rollup-cut-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-aged-0-30")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-aged-31-60")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-aged-61")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("header-people-count")).toHaveText("2");
  await expect(pg_uma.getByTestId("header-claims-DRAFT-count")).toHaveText("1");
  await expect(pg_uma.getByTestId("header-claims-OPEN-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-claims-PENDING-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-claims-SETTLED-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-claims-VOID-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-claims-REVIEW-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("header-overdue-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("my-due-total")).toHaveText("");
  await expect(pg_uma.getByTestId("my-overdue-total")).toHaveText("");
  await expect(pg_uma.getByTestId("my-crew-due-total")).toHaveText("");
  await expect(pg_uma.getByTestId("my-reviews-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("watched-due-total")).toHaveText("0.00");
  expect(await ui.claimAction(pg_uma, c_cam_0, "open")).toBe(true);
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  expect(await ui.delegate(pg_vic, {"user": "wes", "from": "2026-02-10", "to": "2026-03-01"})).toBe(true);
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  await ui.showRetired(pg_wes, true);
  expect(await ui.addClaim(pg_wes, p_ada, {"amount": "25.00", "date": "2026-02-25", "note": "n", "ref": "R-1"})).toBeNull();
  expect(await ui.setTodayTry(pg_wes, "2026-05-22")).toBe(false);
  expect(await ui.setRate(pg_wes, {"grade": "A", "pct": "5.00", "from": "2026-04-28"})).toBe(false);
  await ui.refresh(pg_vic);
  expect(await ui.redate(pg_vic, c_cam_0, "2026-02-25")).toBe(true);
  expect(await ui.dups(pg_vic)).toEqual([]);
  await ui.refresh(pg_vic);
  await expect(pg_vic.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("7.77");
  await expect(pg_vic.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("1.00");
  await expect(pg_vic.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-due")).toHaveText("1.00");
