content.content:
  /** Whether the claim was added while the period its due-by falls in was soft-closed. */
  lateEntry: boolean;
  /** The last sheet-today a reminder was written for the claim; null when never reminded. */
  remindedOn: string | null;
  /** The reason the claim was voided with, from the sheet's void reasons; null when none. */
  voidReason: string | null;
  /** The claim's comments, oldest first. */
  comments: ClaimCommentLine[];
  /** The number of the bulk settle batch that settled the claim (or made it PENDING); null when not settled by one. */
  batch: number | null;
  /** The claim's lines, in the order added; while it has any, its amount is their total. */
  lines: ClaimLineItem[];
  /** The sheet's today when the claim last went to REVIEW; null when it never has. */
  reviewOn: string | null;
  /** The sheet's today when the claim last went to PENDING; null when it never has. */
  pendingOn: string | null;
  /** The user a steward last assigned the claim's review to; null when never assigned. */
  reviewAssigned: string | null;
  /** Whether a steward waived the claim's late charge: from then on it bears none. */
  waived: boolean;
  /** Whether the claim is held: a held claim still counts in every total. */
  held: boolean;
  /** The people the claim is shared with, in the order added. */
  shares: ClaimShareItem[];
}

/** A share of a claim: the holder (another person on the sheet) and their share percent. */
export interface ClaimShareItem {
  holder: number;
  share: string;
}

/**
 * A holder's part of a claim's figure, in whole cents: the figure times the share divided by 100,
 * rounded half to even.
 */
export function sharePart(figure: number, share: string): number {
  // figure cents times share hundredths: ten-thousandths of a cent
  const units = figure * Math.round(Number(share) * 100);
  const sign = units < 0 ? -1 : 1;
  const abs = Math.abs(units);
  const whole = Math.floor(abs / 10000);
  const rest = abs - whole * 10000;
