  /**
   * Compare this sheet with another: per grade of this sheet's summary, the grade, this sheet's
   * due-total for it and the other sheet's (0.00 when no one is on it there); no lines when the
   * other sheet does not exist.
   */
  protected async compareWithSheet(event: Event): Promise<void> {
    event.preventDefault();
    const sheet = this.session.sheet();
    const other = this.compareSheet().trim();
    this.compareLines.set([]);
    if (!other) return;
    let theirs: { exists: boolean; gradeDueTotals: Record<string, string> };
    try {
      theirs = await firstValueFrom(
        this.http.post<{ exists: boolean; gradeDueTotals: Record<string, string> }>('/api/rollup/compare/list', {
          sheet: other,
        }),
      );
    } catch {
      return;
    }
    if (this.session.sheet() !== sheet || !theirs.exists) return;
    this.compareLines.set(
      this.gradeSummary().map((g) => `${g.grade} ${g.dueTotal} ${theirs.gradeDueTotals[g.grade] ?? '0.00'}`),
    );
  }

  /** What the person owes, in whole cents: the sum of their figures held to the sheet's cap less their cut total. */
  protected dueOf(p: Person): number | null {
    const sum = this.figuresOf(p);
    const room = this.roomOf(p);
    return sum === null || room === null ? sum : Math.min(sum, room);
  }

  /** The person's cut total, in whole cents: 0 when no pool shows them a cut. */
  protected cutTotalOf(id: number): number {
    return this.cutTotals().get(id) ?? 0;
  }

  /** How far the sum of the person's figures is above the cap less their cut total, in whole cents; 0 otherwise. */
  protected excessOf(p: Person): number {
    const sum = this.figuresOf(p);
    const room = this.roomOf(p);
    return sum === null || room === null ? 0 : Math.max(sum - room, 0);
  }

  /** The sheet's cap less the person's cut total (not below 0), in whole cents; null for no cap. */
  private roomOf(p: Person): number | null {
    const cap = this.capCents();
    return cap === null ? null : Math.max(cap - this.cutTotalOf(p.id), 0);
  }

  /**
   * The sum of the figures of the person's claims that count, in whole cents. Null when their
   * grade in force on the sheet's today has no rate in force then, unless a claim that counts has
   * a figure.
   */
  private figuresOf(p: Person): number | null {
    const figures = this.claimsOf(p.id)
      .filter((c) => countsFor(p, c, this.session.figureDay()))
      .map((c) => {
        const f = chargedDueCents(c, this.rates(), gradeOn(p.grades, c.date), this.floors(), this.lateness(), this.roundOn(c));
        return f === null ? null : ownPart(c, f);
      });
    const held = this.heldParts().get(p.id);
    if (this.pctOf().get(this.gradeToday(p)) === undefined && figures.every((f) => f === null) && held === undefined) {
      return null;
    }
    return figures.reduce<number>((sum, f) => sum + (f ?? 0), 0) + (held ? held.settled + held.open : 0);
  }

  /**
   * Per holder (by person id), the parts they hold of the claims that count for their own person and
   * have a figure, in whole cents, split into those of SETTLED claims and those of OPEN and PENDING
   * ones; a person holding none is absent.
   */
  private readonly heldParts = computed(() => {
    const today = this.session.figureDay();
    const parts = new Map<number, { settled: number; open: number }>();
    for (const c of this.claims()) {
      if ((c.shares ?? []).length === 0) continue;
      const owner = this.peopleById().get(c.personId);
      if (owner === undefined || !countsFor(owner, c, today)) continue;
      const figure = chargedDueCents(c, this.rates(), gradeOn(owner.grades, c.date), this.floors(), this.lateness(), this.roundOn(c));
      if (figure === null) continue;
      for (const s of c.shares) {
        const held = parts.get(s.holder) ?? { settled: 0, open: 0 };
        const part = sharePart(figure, s.share);
        parts.set(s.holder, isOpen(c) ? { ...held, open: held.open + part } : { ...held, settled: held.settled + part });
      }
    }
    return parts;
  });

  /**
   * The figures of the person's claims that count, in whole cents, split into those of their
   * SETTLED claims and those of their OPEN and PENDING claims; together the sum before the cap.
   */
  protected settledOpenOf(p: Person): { settled: number; open: number } {
    const out = { settled: 0, open: 0 };
    for (const c of this.claimsOf(p.id)) {
      if (!countsFor(p, c, this.session.figureDay())) continue;
      const figure = chargedDueCents(c, this.rates(), gradeOn(p.grades, c.date), this.floors(), this.lateness(), this.roundOn(c));
      const own = figure === null ? 0 : ownPart(c, figure);
      if (isOpen(c)) out.open += own;
      else out.settled += own;
    }
    const held = this.heldParts().get(p.id);
    if (held) {
      out.settled += held.settled;
      out.open += held.open;
    }
    return out;
  }

  /**
   * Whether the person is active: they have an OPEN or PENDING claim that counts dated within the
   * 30 days up to and including the sheet's today.
   */
  protected isActive(p: Person): boolean {
    const today = this.session.figureDay();
    if (!today) return false;
    const since = plusDays(today, -29);
    return this.claimsOf(p.id).some(
      (c) => isOpen(c) && countsFor(p, c, today) && c.date >= since && c.date <= today,
    );
  }

  /**
   * The figures of the person's OPEN and PENDING claims that count, in whole cents, by age on the
   * sheet's today: 0 to 30 days (a claim dated after today included), 31 to 60, and 61 or more.
